'use strict';
(function(){
const $=s=>document.querySelector(s);let endpoint=window.SchoolSyncConfig?.endpoint||'',busy=false,timer;
try{endpoint=localStorage.getItem('school-summary-endpoint')||endpoint;}catch{}
const input=$('#sync-endpoint'),message=$('#sync-status');input.value=endpoint;
function validURL(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='script.google.com'&&/^\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(u.pathname)&&!u.search&&!u.hash;}catch{return false;}}
function validate(data){if(data?.error)throw Error(data.error);if(data?.schema!==1||!data.groups?.all||!Number.isFinite(Date.parse(data.generated_at)))throw Error('Неизвестный формат статистики.');for(const group of ['all','5–7','8–9','10–11','other']){const s=data.groups[group];if(!s||!Number.isInteger(s.participants)||s.participants<0||!(s.average===null||Number.isFinite(s.average)&&s.average>=1&&s.average<=5))throw Error('Некорректная статистика группы.');for(const f of SchoolData.fields.filter(x=>!['class_group','suggestion'].includes(x.key))){const d=s.results?.[f.key];if(!d||!Number.isInteger(d.answered)||d.answered<0||d.answered>s.participants||!Array.isArray(d.items))throw Error('Некорректные данные вопроса.');for(const x of d.items)if(typeof x.label!=='string'||x.label.length>200||!Number.isInteger(x.count)||x.count<0||x.count>d.answered||x.percent!==Math.round(x.count/d.answered*100))throw Error('Некорректные значения диаграммы.');}}return data;}
function notify(text,error=false){message.textContent=text;message.classList.toggle('error',error);}
function request(url){return new Promise((resolve,reject)=>{let settled=false;const callback='schoolSurveyCallback_'+Date.now()+Math.floor(Math.random()*10000),script=document.createElement('script');const timeout=setTimeout(()=>finish(Error('Google не ответил вовремя. Сохранённые результаты остаются на экране.')),25000);function finish(error,data){if(settled)return;settled=true;clearTimeout(timeout);script.remove();if(error){window[callback]=()=>{};setTimeout(()=>delete window[callback],300000);}else delete window[callback];error?reject(error):resolve(data);}window[callback]=data=>{try{finish(null,validate(data));}catch(e){finish(e);}};script.onerror=()=>finish(Error('Не удалось подключиться к Google. Проверь интернет и доступ к веб-приложению.'));script.src=url+'?callback='+callback;document.body.append(script);});}
async function refresh(){if(busy||!endpoint)return;if(document.hidden)return;if(!validURL(endpoint)){notify('Нужен адрес https://script.google.com/macros/s/…/exec',true);return;}busy=true;$('#sync-refresh').disabled=true;notify('Обновляем статистику из Google Forms…');try{let data;const hosted=location.protocol==='https:'&&location.hostname!=='localhost'&&location.hostname!=='127.0.0.1';const defaultEndpoint=endpoint===window.SchoolSyncConfig?.endpoint;if(hosted&&defaultEndpoint){const response=await fetch('/api/summary',{signal:AbortSignal.timeout(25000),credentials:'omit'});if(response.status===404){data=await request(endpoint);}else{const payload=await response.json();if(!response.ok)throw Error(payload.error||'Не удалось обновить статистику.');data=validate(payload);}}else data=await request(endpoint);window.dispatchEvent(new CustomEvent('school-summary',{detail:data}));notify('Связь установлена · ответов: '+data.groups.all.participants+' · обновлено '+new Date(data.generated_at).toLocaleString('ru-RU')+'. Автообновление раз в минуту.');}catch(e){notify(e.name==='TimeoutError'?'Google не ответил вовремя. Сохранённые результаты остаются на экране.':e.message,true);}finally{busy=false;$('#sync-refresh').disabled=false;}}
$('#sync-connect').addEventListener('click',()=>{const next=input.value.trim();if(!validURL(next)){notify('Вставь адрес опубликованного веб-приложения Google, заканчивающийся на /exec.',true);return;}endpoint=next;try{localStorage.setItem('school-summary-endpoint',endpoint);}catch{}refresh();});
$('#sync-refresh').addEventListener('click',refresh);
$('#sync-show-live').addEventListener('click',()=>{window.dispatchEvent(new Event('school-show-live'));refresh();});
timer=setInterval(refresh,window.SchoolSyncConfig?.interval||60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
if(endpoint)refresh();else notify('Автообновление подготовлено. Осталось разрешить Google доступ скрипта к форме и получить адрес подключения. Пока показан сохранённый срез.');
})();
